const ecommerceAirflowCode = `from datetime import timedelta\nimport pendulum\nfrom airflow.sdk import dag, task, PokeReturnValue\n\n@dag(\n    dag_id="daily_ecommerce_sales",\n    schedule="0 6 * * *",\n    start_date=pendulum.datetime(2026, 1, 1, tz="UTC"),\n    catchup=False,\n    tags=["learning", "ecommerce"],\n)\ndef daily_ecommerce_sales():\n    @task.sensor(poke_interval=60, timeout=1800, mode="reschedule")\n    def wait_for_orders() -> PokeReturnValue:\n        # Real code would check durable storage.\n        return PokeReturnValue(is_done=True, xcom_value="2026-09-17")\n\n    @task(retries=2, retry_delay=timedelta(minutes=5))\n    def ingest_orders(partition: str):\n        return {"partition": partition, "rows": 12490}\n\n    @task\n    def validate_raw(load_result: dict):\n        assert load_result["rows"] > 0\n\n    @task\n    def run_dbt_staging():\n        # Simulator cross-links this task to dbt staging models.\n        pass\n\n    @task\n    def run_dbt_marts():\n        pass\n\n    @task\n    def run_dbt_tests():\n        pass\n\n    @task\n    def publish_sales():\n        pass\n\n    partition = wait_for_orders()\n    loaded = ingest_orders(partition)\n    checked = validate_raw(loaded)\n    staged = run_dbt_staging()\n    marts = run_dbt_marts()\n    tests = run_dbt_tests()\n    published = publish_sales()\n    checked >> staged >> marts >> tests >> published\n\ndaily_ecommerce_sales()`;

const clickstreamAirflowCode = `import pendulum\nfrom airflow.sdk import dag, task, PokeReturnValue\n\n@dag(\n    dag_id="hourly_clickstream", schedule="15 * * * *",\n    start_date=pendulum.datetime(2026, 1, 1, tz="UTC"), catchup=True,\n)\ndef hourly_clickstream():\n    @task.sensor(poke_interval=30, timeout=900, mode="reschedule")\n    def wait_for_events() -> PokeReturnValue:\n        return PokeReturnValue(is_done=True, xcom_value="hour=13")\n\n    @task(retries=2)\n    def load_events(partition: str):\n        return {"partition": partition, "rows": 88231}\n\n    @task.branch\n    def route_quality(result: dict) -> str:\n        return "transform_sessions" if result["rows"] > 1000 else "quarantine_events"\n\n    @task\n    def transform_sessions(): pass\n    @task\n    def quarantine_events(): pass\n    @task\n    def build_funnel(): pass\n    @task\n    def test_funnel_quality(): pass\n    @task\n    def publish_hourly_metrics(): pass\n\n    @task(trigger_rule="none_failed_min_one_success")\n    def finalize_hour(): pass\n\n    p = wait_for_events()\n    loaded = load_events(p)\n    branch = route_quality(loaded)\n    good = transform_sessions()\n    bad = quarantine_events()\n    funnel = build_funnel()\n    tests = test_funnel_quality()\n    publish = publish_hourly_metrics()\n    finish = finalize_hour()\n    branch >> [good, bad]\n    good >> funnel >> tests >> publish\n    [bad, publish] >> finish\n\nhourly_clickstream()`;

const financeAirflowCode = `import pendulum\nfrom airflow.sdk import dag, task\n\n@dag(\n    dag_id="daily_finance_reconciliation",\n    schedule="0 7 * * 1-5",\n    start_date=pendulum.datetime(2026, 1, 1, tz="UTC"),\n    catchup=False,\n)\ndef finance_reconciliation():\n    @task(retries=1)\n    def load_bank_transactions(): pass\n\n    @task(retries=1)\n    def load_ledger(): pass\n\n    @task\n    def run_dbt_reconciliation(): pass\n\n    @task\n    def control_totals(): pass\n\n    @task\n    def publish_exceptions(): pass\n\n    [load_bank_transactions(), load_ledger()] >> run_dbt_reconciliation() >> control_totals() >> publish_exceptions()\n\nfinance_reconciliation()`;

const mockMarketplaceAirflowCode = `from datetime import timedelta\nimport pendulum\nfrom airflow.sdk import dag, task, PokeReturnValue\n\n@dag(\n    dag_id="daily_fulfillment_sla",\n    schedule="0 7 * * *",\n    start_date=pendulum.datetime(2026, 1, 1, tz="UTC"),\n    catchup=False,\n    tags=["mock-project", "marketplace"],\n)\ndef daily_fulfillment_sla():\n    @task\n    def load_order_events():\n        return {"rows": 18640, "partition": "2026-09-16"}\n\n    @task.sensor(poke_interval=60, timeout=1800, mode="reschedule")\n    def wait_for_shipments() -> PokeReturnValue:\n        return PokeReturnValue(is_done=True, xcom_value="shipments/2026-09-16.csv")\n\n    @task(retries=2, retry_delay=timedelta(minutes=3))\n    def load_shipments(path: str):\n        return {"rows": 5921, "path": path}\n\n    @task\n    def validate_raw(order_result: dict, shipment_result: dict):\n        assert order_result["rows"] > 0 and shipment_result["rows"] > 0\n\n    @task\n    def run_dbt_core(): pass\n\n    @task\n    def run_dbt_marts(): pass\n\n    @task\n    def run_dbt_tests(): pass\n\n    @task\n    def publish_sla_dashboard(): pass\n\n    orders = load_order_events()\n    shipment_path = wait_for_shipments()\n    shipments = load_shipments(shipment_path)\n    raw_ok = validate_raw(orders, shipments)\n    core = run_dbt_core()\n    marts = run_dbt_marts()\n    tests = run_dbt_tests()\n    publish = publish_sla_dashboard()\n    raw_ok >> core >> marts >> tests >> publish\n\ndaily_fulfillment_sla()`;

